// Package contextwindow selects the highest-value context items for a bounded
// model window. It is deterministic and local-only: BM25 relevance plus small
// recency/error/priority signals, no embeddings and no network.
package contextwindow

import (
	"math"
	"regexp"
	"sort"
	"strings"
	"time"
	"unicode"

	"github.com/JuliusBrussee/caveman/engine/tokens"
)

const (
	defaultMaxTokens       = 8000
	defaultRecencyHalfLife = 6 * time.Hour
	defaultRecencyWeight   = 0.15
	defaultErrorBoost      = 0.8
	bm25K1                 = 1.5
	bm25B                  = 0.75
)

var errorSignalRe = regexp.MustCompile(`(?i)\b(ERROR|FATAL|PANIC|EXCEPTION|TRACEBACK|FAIL|FAILED|FAILURE|SECURITY|REGRESSION)\b`)

// Item is one candidate context fragment. Tokens may be supplied by a caller
// that already counted the item; when zero, Pack uses the engine token counter.
type Item struct {
	ID        string
	Text      string
	Tokens    int
	Timestamp time.Time
	Priority  float64
	Pin       bool
}

// Options controls context packing. MaxTokens is the total window budget;
// ReserveTokens is left unused for the next model response/tool call.
type Options struct {
	MaxTokens       int
	ReserveTokens   int
	Now             time.Time
	RecencyHalfLife time.Duration
	RecencyWeight   float64
	ErrorBoost      float64
	Counter         tokens.Counter
}

// Selected is an item chosen for the packed context.
type Selected struct {
	Item
	Score float64
}

// Result is the packed context and accounting for omitted items.
type Result struct {
	Items         []Selected
	TokensUsed    int
	TokensBefore  int
	TokensSaved   int
	DeferredCount int
}

// Pack selects the best items that fit within the token budget. It scores in
// relevance order but returns selected items in their original order so message
// chronology stays intact.
func Pack(query string, items []Item, opts Options) Result {
	if opts.MaxTokens <= 0 {
		opts.MaxTokens = defaultMaxTokens
	}
	if opts.RecencyHalfLife <= 0 {
		opts.RecencyHalfLife = defaultRecencyHalfLife
	}
	if opts.RecencyWeight == 0 {
		opts.RecencyWeight = defaultRecencyWeight
	}
	if opts.ErrorBoost == 0 {
		opts.ErrorBoost = defaultErrorBoost
	}
	if opts.Counter == nil {
		opts.Counter = tokens.Default()
	}
	budget := opts.MaxTokens - opts.ReserveTokens
	if budget < 0 {
		budget = 0
	}
	now := opts.Now
	if now.IsZero() {
		now = latestTimestamp(items)
	}

	normalized := make([]Item, len(items))
	tokensBefore := 0
	for i, item := range items {
		normalized[i] = item
		if normalized[i].Tokens <= 0 {
			normalized[i].Tokens = opts.Counter.Count([]byte(item.Text))
		}
		tokensBefore += normalized[i].Tokens
	}

	bm25 := bm25Scores(query, normalized)
	candidates := make([]candidate, len(normalized))
	for i, item := range normalized {
		score := bm25[i] + item.Priority
		if !item.Timestamp.IsZero() && !now.IsZero() {
			age := now.Sub(item.Timestamp)
			if age < 0 {
				age = 0
			}
			score += opts.RecencyWeight * math.Exp(-float64(age)/float64(opts.RecencyHalfLife))
		}
		if errorSignalRe.MatchString(item.Text) {
			score += opts.ErrorBoost
		}
		if item.Pin {
			score += 1_000_000
		}
		candidates[i] = candidate{index: i, item: item, score: score}
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if candidates[i].score == candidates[j].score {
			return candidates[i].index < candidates[j].index
		}
		return candidates[i].score > candidates[j].score
	})

	var selected []candidate
	used := 0
	for _, c := range candidates {
		if c.item.Tokens <= 0 {
			continue
		}
		if used+c.item.Tokens > budget {
			continue
		}
		selected = append(selected, c)
		used += c.item.Tokens
	}
	sort.SliceStable(selected, func(i, j int) bool { return selected[i].index < selected[j].index })

	out := make([]Selected, len(selected))
	for i, c := range selected {
		out[i] = Selected{Item: c.item, Score: c.score}
	}
	return Result{
		Items:         out,
		TokensUsed:    used,
		TokensBefore:  tokensBefore,
		TokensSaved:   max(0, tokensBefore-used),
		DeferredCount: len(items) - len(out),
	}
}

type candidate struct {
	index int
	item  Item
	score float64
}

func latestTimestamp(items []Item) time.Time {
	var latest time.Time
	for _, item := range items {
		if item.Timestamp.After(latest) {
			latest = item.Timestamp
		}
	}
	return latest
}

// BM25 scores each document against the query using the same deterministic Okapi
// BM25 the context packer uses (k1=1.5, b=0.75) — no embeddings, no network. The
// returned scores are unnormalized and comparable only within the slice. It is
// exported so other deterministic compressors reuse the single BM25 implementation
// rather than growing a second one.
func BM25(query string, docs []string) []float64 {
	items := make([]Item, len(docs))
	for i, d := range docs {
		items[i] = Item{Text: d}
	}
	return bm25Scores(query, items)
}

func bm25Scores(query string, items []Item) []float64 {
	queryTerms := termFreq(query)
	out := make([]float64, len(items))
	if len(queryTerms) == 0 || len(items) == 0 {
		return out
	}
	docs := make([]map[string]int, len(items))
	docLen := make([]int, len(items))
	df := map[string]int{}
	totalLen := 0
	for i, item := range items {
		tf := termFreq(item.Text)
		docs[i] = tf
		for _, count := range tf {
			docLen[i] += count
		}
		totalLen += docLen[i]
		for term := range tf {
			df[term]++
		}
	}
	avgdl := 1.0
	if totalLen > 0 {
		avgdl = float64(totalLen) / float64(len(items))
	}
	for i := range items {
		for term := range queryTerms {
			tf := float64(docs[i][term])
			if tf == 0 {
				continue
			}
			idf := math.Log(1 + (float64(len(items))-float64(df[term])+0.5)/(float64(df[term])+0.5))
			denom := tf + bm25K1*(1-bm25B+bm25B*float64(docLen[i])/avgdl)
			out[i] += idf * (tf * (bm25K1 + 1)) / denom
		}
	}
	return out
}

func termFreq(text string) map[string]int {
	freq := map[string]int{}
	var current strings.Builder
	flush := func() {
		tok := current.String()
		if len(tok) >= 2 && !stopwords[tok] {
			freq[tok]++
		}
		current.Reset()
	}
	for _, r := range strings.ToLower(text) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			current.WriteRune(r)
		} else {
			flush()
		}
	}
	flush()
	return freq
}

var stopwords = map[string]bool{
	"a": true, "an": true, "and": true, "are": true, "as": true, "at": true,
	"be": true, "by": true, "for": true, "from": true, "how": true, "in": true,
	"is": true, "it": true, "of": true, "on": true, "or": true, "that": true,
	"the": true, "this": true, "to": true, "was": true, "what": true, "when": true,
	"where": true, "which": true, "who": true, "why": true, "with": true,
}

// @ts-nocheck
//
// Token Rotation Map (codex-multi-auth pattern) — extracted from
// open-sse/services/tokenRefresh.ts. See ../shared.ts for provenance notes.
//
// When a rotating-token provider (Codex, Kimi, GitLab Duo, etc.) refreshes,
// the old refresh_token is consumed and a new one is issued. Any subsequent
// caller arriving with the OLD token would, without protection, hit upstream
// and trigger "refresh_token_reused" — which Auth0 treats as a security event
// and invalidates the entire token family.
//
// This in-memory map caches RECENT rotations so a stale caller can be redirected
// to the new tokens WITHOUT touching upstream. The DB staleness check inside
// the per-connection mutex covers the same scenario when connectionId is known,
// but not all callers pass connectionId (e.g., legacy code paths, retries that
// snapshot credentials before the rotation lands in DB).
//
// Ported from ndycode/codex-multi-auth (lib/refresh-queue.ts:218-248), the only
// publicly known tool that reliably sustains multiple Codex OAuth accounts.
//
// Key format: `provider:sha256(oldRefreshToken)`
// Value: { result: tokens, expiresAt: ms_since_epoch }
import { pbkdf2Sync } from "node:crypto";

const CACHE_SECRET = "omniroute-token-cache";

/**
 * Build the dedup/rotation cache key for a (provider, refreshToken) pair.
 * Hashed so a raw refresh_token never sits in a Map key in plaintext.
 */
export function getRefreshCacheKey(provider, refreshToken) {
  const tokenHash = pbkdf2Sync(refreshToken, CACHE_SECRET, 1000, 32, "sha256").toString("hex");
  return `${provider}:${tokenHash}`;
}

type RotationEntry = {
  result: { accessToken: string; refreshToken: string; expiresIn?: number; expiresAt?: string };
  expiresAt: number;
};
const tokenRotationMap = new Map<string, RotationEntry>();
const ROTATION_MAP_TTL_MS = 60 * 1000; // 60 seconds — long enough to catch in-flight stale callers

function cleanupRotationMap(now: number = Date.now()): void {
  if (tokenRotationMap.size === 0) return;
  for (const [key, entry] of tokenRotationMap.entries()) {
    if (entry.expiresAt <= now) tokenRotationMap.delete(key);
  }
}

export function lookupRotation(provider: string, refreshToken: string): RotationEntry | undefined {
  cleanupRotationMap();
  const key = getRefreshCacheKey(provider, refreshToken);
  const entry = tokenRotationMap.get(key);
  if (!entry) return undefined;
  if (entry.expiresAt <= Date.now()) {
    tokenRotationMap.delete(key);
    return undefined;
  }
  return entry;
}

export function recordRotation(
  provider: string,
  oldRefreshToken: string,
  result: { accessToken: string; refreshToken: string; expiresIn?: number; expiresAt?: string }
): void {
  if (!oldRefreshToken || !result.refreshToken || oldRefreshToken === result.refreshToken) {
    return;
  }
  const key = getRefreshCacheKey(provider, oldRefreshToken);
  tokenRotationMap.set(key, {
    result,
    expiresAt: Date.now() + ROTATION_MAP_TTL_MS,
  });
}

// Exported for tests + diagnostics; not part of the public API surface.
export function _getTokenRotationMapStats(): { size: number; entries: number } {
  cleanupRotationMap();
  return { size: tokenRotationMap.size, entries: tokenRotationMap.size };
}

export function _clearTokenRotationMap(): void {
  tokenRotationMap.clear();
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  estimateTokens,
  isInlineBase64DocumentBlock,
  isInlineBase64ImageBlock,
  pruneOlderInlineImages,
} from "../../open-sse/services/contextManager.ts";

/**
 * #10840 — a base64 file payload (PDF and friends) was measured as ordinary
 * prompt text, so large documents were rejected on the context limit before
 * ever reaching a provider's native document pipeline.
 *
 * The estimate must not depend on which wire shape the document arrived in:
 * the Gemini `inlineData` matcher never inspected media type, so the SAME PDF
 * was already budgeted at the bounded image estimate there while the OpenAI
 * `file` and Claude `document` shapes were measured character by character.
 */

function base64Payload(approxBytes: number): string {
  return Buffer.alloc(approxBytes, 65).toString("base64");
}

const PDF_B64 = base64Payload(1_000_000); // ~1 MB document
const PDF_DATA_URL = `data:application/pdf;base64,${PDF_B64}`;

const SHAPES: Array<[string, Record<string, unknown>]> = [
  ["gemini inlineData", { inlineData: { mimeType: "application/pdf", data: PDF_B64 } }],
  [
    "claude document",
    { type: "document", source: { type: "base64", media_type: "application/pdf", data: PDF_B64 } },
  ],
  ["openai file.file_data", { type: "file", file: { filename: "d.pdf", file_data: PDF_DATA_URL } }],
  ["openai file.data", { type: "file", file: { filename: "d.pdf", data: PDF_DATA_URL } }],
  ["responses input_file", { type: "input_file", filename: "d.pdf", file_data: PDF_DATA_URL }],
];

test("#10840: a base64 document is never measured as raw prompt text", () => {
  for (const [name, block] of SHAPES) {
    const tokens = estimateTokens({
      messages: [{ role: "user", content: [{ type: "text", text: "Summarise this." }, block] }],
    });
    assert.ok(
      tokens < 5_000,
      `${name}: expected a bounded document estimate, got ${tokens} tokens for a ~1MB file`
    );
  }
});

test("#10840: every wire shape of the same document agrees", () => {
  const counts = SHAPES.map(([, block]) => estimateTokens(block));
  const unique = [...new Set(counts)];
  assert.equal(
    unique.length,
    1,
    `the same document must cost the same regardless of shape, got ${JSON.stringify(
      SHAPES.map(([n], i) => `${n}=${counts[i]}`)
    )}`
  );
});

test("#10840: a remote file URL still flows through the text path", () => {
  // Not base64 transport — nothing to exclude, and it is short anyway.
  const block = { type: "file", file: { filename: "d.pdf", file_data: "https://x.test/d.pdf" } };
  assert.equal(isInlineBase64DocumentBlock(block), false);
});

test("#10840: document detection stays separate from image detection", () => {
  const doc = SHAPES[2][1];
  const img = { type: "image_url", image_url: { url: "data:image/png;base64,AAAA" } };

  assert.equal(isInlineBase64DocumentBlock(doc), true);
  assert.equal(isInlineBase64ImageBlock(doc), false, "a document must not register as an image");
  assert.equal(isInlineBase64ImageBlock(img), true);
  assert.equal(isInlineBase64DocumentBlock(img), false);
});

test("#10840: pruneOlderInlineImages still ignores documents", () => {
  // Dropping an attached PDF is not the same decision as dropping an old
  // screenshot, so the pruner must keep its image-only scope.
  const messages = [
    {
      role: "user",
      content: [{ type: "file", file: { filename: "a.pdf", file_data: PDF_DATA_URL } }],
    },
    {
      role: "user",
      content: [{ type: "file", file: { filename: "b.pdf", file_data: PDF_DATA_URL } }],
    },
    {
      role: "user",
      content: [{ type: "file", file: { filename: "c.pdf", file_data: PDF_DATA_URL } }],
    },
  ];

  const { pruned, messages: after } = pruneOlderInlineImages(messages, { keepLatest: 1 });

  assert.equal(pruned, 0, "documents must not be pruned by the image pruner");
  assert.deepEqual(after, messages);
});

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

import mlx.core as mx
import numpy as np
from transformers import AutoTokenizer


@dataclass(frozen=True, slots=True)
class TokenizerOutput:
    input_ids: mx.array
    attention_mask: mx.array


class Flux2Tokenizer:
    def __init__(self, model_path: str | Path, max_length: int = 512) -> None:
        self.max_length = max_length
        self.tokenizer = AutoTokenizer.from_pretrained(
            str(Path(model_path).expanduser() / "tokenizer"),
            local_files_only=True,
            use_fast=True,
        )

    def _format_prompts(self, prompt: str | list[str]) -> list[str]:
        prompts = [prompt] if isinstance(prompt, str) else list(prompt)
        prompts = [p if p is not None else "" for p in prompts]
        return [
            self.tokenizer.apply_chat_template(
                [{"role": "user", "content": p}],
                tokenize=False,
                add_generation_prompt=True,
                enable_thinking=False,
            )
            for p in prompts
        ]

    def count_tokens(self, prompt: str | list[str]) -> int:
        prompts = self._format_prompts(prompt)
        if all(p == "" for p in prompts):
            return 0
        tokens = self.tokenizer(
            prompts,
            padding=False,
            truncation=False,
            add_special_tokens=True,
            return_tensors=None,
        )
        return max(len(ids) for ids in tokens["input_ids"])

    def tokenize(
        self, prompt: str | list[str], max_length: int | None = None
    ) -> TokenizerOutput:
        prompts = self._format_prompts(prompt)
        if all(p == "" for p in prompts):
            batch = len(prompts)
            return TokenizerOutput(
                input_ids=mx.array(np.empty((batch, 0), dtype=np.int32)),
                attention_mask=mx.array(np.empty((batch, 0), dtype=np.int32)),
            )
        tokens = self.tokenizer(
            prompts,
            padding="max_length",
            max_length=max_length or self.max_length,
            truncation=True,
            add_special_tokens=True,
            return_tensors="np",
        )
        return TokenizerOutput(
            input_ids=mx.array(tokens["input_ids"]),
            attention_mask=mx.array(tokens["attention_mask"]),
        )


__all__ = ["Flux2Tokenizer", "TokenizerOutput"]

import codecs
import json
from copy import copy
from functools import partial
from json import JSONDecodeError
from typing import List, Optional

from transformers import AutoTokenizer

REPLACEMENT_CHAR = "\ufffd"


def _remove_space(x):
    if x and x[0] == " ":
        return x[1:]
    return x


class StreamingDetokenizer:
    """The streaming detokenizer interface so that we can detokenize one token at a time.

    Example usage is as follows:

        detokenizer = ...

        # Reset the tokenizer state
        detokenizer.reset()

        for token in generate(...):
            detokenizer.add_token(token.item())

            # Contains the whole text so far. Some tokens may not be included
            # since it contains whole words usually.
            detokenizer.text

            # Contains the printable segment (usually a word) since the last
            # time it was accessed
            detokenizer.last_segment

            # Contains all the tokens added so far
            detokenizer.tokens

        # Make sure that we detokenize any remaining tokens
        detokenizer.finalize()

        # Now detokenizer.text should match tokenizer.decode(detokenizer.tokens)
    """

    __slots__ = ("text", "tokens", "offset")

    def reset(self):
        raise NotImplementedError()

    def add_token(self, token, skip_special_token_ids: List[int] = []):
        raise NotImplementedError()

    def finalize(self):
        raise NotImplementedError()

    @property
    def last_segment(self):
        """Return the last segment of readable text since last time this property was accessed."""
        text = self.text
        if text and text[-1] != REPLACEMENT_CHAR:
            segment = text[self.offset :]
            self.offset = len(text)
            return segment
        return ""


class NaiveStreamingDetokenizer(StreamingDetokenizer):
    """NaiveStreamingDetokenizer relies on the underlying tokenizer
    implementation and should work with every tokenizer.

    Its complexity is O(T^2) where T is the longest line since it will
    repeatedly detokenize the same tokens until a new line is generated.
    """

    def __init__(self, tokenizer):
        self._tokenizer = tokenizer
        self._tokenizer.decode([0])
        self.reset()

    def __copy__(self):
        return type(self)(self._tokenizer)

    def reset(self):
        self.offset = 0
        self._tokens = []
        self._text = ""
        self._current_tokens = []
        self._current_text = ""

    def add_token(self, token, skip_special_token_ids: List[int] = []):
        if token in skip_special_token_ids:
            return
        self._current_tokens.append(token)

    def finalize(self):
        self._tokens.extend(self._current_tokens)
        self._text += self._tokenizer.decode(self._current_tokens)
        self._current_tokens = []
        self._current_text = ""

    @property
    def text(self):
        if self._current_tokens:
            self._current_text = self._tokenizer.decode(self._current_tokens)
        if self._current_text and self._current_text[-1] == "\n":
            self._tokens.extend(self._current_tokens)
            self._text += self._current_text
            self._current_tokens.clear()
            self._current_text = ""
        return self._text + self._current_text

    @property
    def tokens(self):
        return self._tokens


class SPMStreamingDetokenizer(StreamingDetokenizer):
    """A streaming detokenizer for SPM models.

    It adds tokens to the text if the next token starts with the special SPM
    underscore which results in linear complexity.

    Handles UTF-8 byte tokens (like <0xE5><0xA4><0xA2>) by accumulating them
    and decoding as UTF-8 bytes, which is necessary for multi-byte characters
    like Chinese that may not be in the vocabulary.
    """

    def __init__(self, tokenizer, trim_space=True):
        self.trim_space = trim_space

        # Extract the tokens in a list from id to text
        self.tokenmap = [None] * len(tokenizer.vocab)
        self.is_byte_token = [False] * len(tokenizer.vocab)
        self.byte_value = [0] * len(tokenizer.vocab)

        for value, tokenid in tokenizer.vocab.items():
            self.tokenmap[tokenid] = value
            # Mark byte tokens and store their byte value
            if value.startswith("<0x") and len(value) >= 6 and value[5] == ">":
                self.is_byte_token[tokenid] = True
                self.byte_value[tokenid] = int(value[3:5], 16)

        self.reset()

    def reset(self):
        self.offset = 0
        self._unflushed = ""
        self._byte_buffer = bytearray()
        self.text = ""
        self.tokens = []

    def _flush_bytes(self):
        """Decode accumulated bytes as UTF-8 and append to unflushed text."""
        if self._byte_buffer:
            try:
                decoded = self._byte_buffer.decode("utf-8")
                self._unflushed += decoded
            except UnicodeDecodeError:
                # If decoding fails, use replacement character
                self._unflushed += self._byte_buffer.decode("utf-8", errors="replace")
            self._byte_buffer = bytearray()

    def add_token(self, token, skip_special_token_ids: List[int] = []):
        if token in skip_special_token_ids:
            return

        if self.is_byte_token[token]:
            # Accumulate byte tokens
            self._byte_buffer.append(self.byte_value[token])
            return

        # Flush any accumulated bytes before processing regular token
        self._flush_bytes()

        v = self.tokenmap[token]
        if v and v[0] == "\u2581":
            if self.text or not self.trim_space:
                self.text += self._unflushed.replace("\u2581", " ")
            else:
                self.text = _remove_space(self._unflushed.replace("\u2581", " "))
            self._unflushed = v
        else:
            self._unflushed += v

    def finalize(self):
        # Flush any remaining bytes
        self._flush_bytes()

        if self.text or not self.trim_space:
            self.text += self._unflushed.replace("\u2581", " ")
        else:
            self.text = _remove_space(self._unflushed.replace("\u2581", " "))
        self._unflushed = ""


class BPEStreamingDetokenizer(StreamingDetokenizer):
    """A streaming detokenizer for OpenAI style BPE models.

    It adds tokens to the text if the next token starts with a space similar to
    the SPM detokenizer.
    """

    _byte_decoder = None

    def __init__(self, tokenizer, trim_space=False):
        self.trim_space = trim_space

        # Extract the tokens in a list from id to text
        self.tokenmap = [None] * len(tokenizer.vocab)
        for value, tokenid in tokenizer.vocab.items():
            self.tokenmap[tokenid] = value

        self.reset()

        # Make the BPE byte decoder from
        # https://github.com/openai/gpt-2/blob/master/src/encoder.py
        self.make_byte_decoder()

    def reset(self):
        self.offset = 0
        self._unflushed = ""
        self.text = ""
        self.tokens = []

    def add_token(self, token, skip_special_token_ids: List[int] = []):
        if token in skip_special_token_ids:
            return
        v = self.tokenmap[token]
        # if the token starts with space
        if self._byte_decoder[v[0]] == 32:
            current_text = bytearray(
                self._byte_decoder[c] for c in self._unflushed
            ).decode("utf-8", errors="replace")
            if self.text or not self.trim_space:
                self.text += current_text
            else:
                self.text += _remove_space(current_text)
            self._unflushed = v
        else:
            self._unflushed += v

    def finalize(self):
        try:
            current_text = bytearray(
                self._byte_decoder[c] for c in self._unflushed
            ).decode("utf-8", errors="ignore")
            if self.text or not self.trim_space:
                self.text += current_text
            else:
                self.text += _remove_space(current_text)
        except (UnicodeDecodeError, KeyError):
            print(f"Warning: could not decode bytes: {self._unflushed}")
        self._unflushed = ""

    @classmethod
    def make_byte_decoder(cls):
        """See https://github.com/openai/gpt-2/blob/master/src/encoder.py for the rationale."""
        if cls._byte_decoder is not None:
            return

        char_to_bytes = {}
        limits = [
            0,
            ord("!"),
            ord("~") + 1,
            ord("¡"),
            ord("¬") + 1,
            ord("®"),
            ord("ÿ") + 1,
        ]
        n = 0
        for i, (start, stop) in enumerate(zip(limits, limits[1:])):
            if i % 2 == 0:
                for b in range(start, stop):
                    char_to_bytes[chr(2**8 + n)] = b
                    n += 1
            else:
                for b in range(start, stop):
                    char_to_bytes[chr(b)] = b
        cls._byte_decoder = char_to_bytes


class _ServerTokenStreamer:
    """Emit server text deltas per token while buffering incomplete UTF-8."""

    def __init__(self, tokenizer, detokenizer):
        self._tokenizer = tokenizer
        self._detokenizer = detokenizer
        self._decoder = None
        self._started = False
        self._tokenmap = None
        self._mode = "delegate"
        self._trim_space = False

        if isinstance(detokenizer, SPMStreamingDetokenizer):
            self._mode = "spm"
            self._tokenmap = detokenizer.tokenmap
            self._trim_space = detokenizer.trim_space
            self._is_byte_token = detokenizer.is_byte_token
            self._byte_value = detokenizer.byte_value
            self._decoder = codecs.getincrementaldecoder("utf-8")("replace")
        elif isinstance(detokenizer, BPEStreamingDetokenizer):
            self._mode = "bpe"
            self._tokenmap = detokenizer.tokenmap
            self._trim_space = detokenizer.trim_space
            self._byte_decoder = detokenizer._byte_decoder
            self._decoder = codecs.getincrementaldecoder("utf-8")("replace")

    def _emit_text(self, text: str) -> str:
        if text and not self._started and self._trim_space and text[0] == " ":
            text = text[1:]
        if text:
            self._started = True
        return text

    def _fallback_decode(self, token: int) -> str:
        try:
            return self._tokenizer.decode([token])
        except Exception:
            return ""

    def _spm_text_for_token(self, token: int) -> str:
        try:
            if self._is_byte_token[token]:
                byte_value = self._byte_value[token]
                return self._decoder.decode(bytes((byte_value,)), final=False)
            value = self._tokenmap[token]
        except (IndexError, TypeError):
            return self._fallback_decode(token)

        if value is None:
            return self._fallback_decode(token)
        return value.replace("\u2581", " ")

    def _bpe_text_for_token(self, token: int) -> str:
        try:
            value = self._tokenmap[token]
        except (IndexError, TypeError):
            return self._fallback_decode(token)

        if value is None:
            return self._fallback_decode(token)

        try:
            token_bytes = bytes(self._byte_decoder[c] for c in value)
        except KeyError:
            return self._fallback_decode(token)
        return self._decoder.decode(token_bytes, final=False)

    def _decode_token(self, token: int) -> str:
        if self._mode == "spm":
            return self._emit_text(self._spm_text_for_token(token))
        if self._mode == "bpe":
            return self._emit_text(self._bpe_text_for_token(token))
        return self._fallback_advance(token, finish_reason=None)

    def _fallback_advance(self, token: int, finish_reason: Optional[str]) -> str:
        if finish_reason == "stop":
            self._detokenizer.finalize()
        else:
            self._detokenizer.add_token(token)
            if finish_reason is not None:
                self._detokenizer.finalize()
        return self._detokenizer.last_segment

    def advance(self, token: int, finish_reason: Optional[str]) -> str:
        if self._mode == "delegate":
            return self._fallback_advance(token, finish_reason)

        parts = []
        if finish_reason != "stop":
            parts.append(self._decode_token(token))
        if finish_reason is not None:
            parts.append(self._emit_text(self._decoder.decode(b"", final=True)))
        return "".join(parts)

    def finalize(self) -> str:
        if self._mode == "delegate":
            self._detokenizer.finalize()
            return self._detokenizer.last_segment
        return self._emit_text(self._decoder.decode(b"", final=True))


class TokenizerWrapper:
    """A wrapper that combines an HF tokenizer and a detokenizer.

    Accessing any attribute other than the ``detokenizer`` is forwarded to the
    huggingface tokenizer.
    """

    def __init__(self, tokenizer, detokenizer_class=NaiveStreamingDetokenizer):
        self._tokenizer = tokenizer
        self._detokenizer = detokenizer_class(tokenizer)

    def __getattr__(self, attr):
        if attr == "detokenizer":
            return self._detokenizer
        else:
            return getattr(self._tokenizer, attr)


def make_streaming_detokenizer(processor):
    """Return an isolated, reset streaming detokenizer for a processor."""
    detokenizer = copy(processor.detokenizer)
    detokenizer.reset()
    return detokenizer


def _match(a, b):
    if type(a) != type(b):
        return False
    if isinstance(a, dict):
        return len(a) == len(b) and all(k in b and _match(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_match(ai, bi) for ai, bi in zip(a, b))

    return a == b


def _is_spm_decoder(decoder):
    _target_description = {
        "type": "Sequence",
        "decoders": [
            {"type": "Replace", "pattern": {"String": "▁"}, "content": " "},
            {"type": "ByteFallback"},
            {"type": "Fuse"},
            {"type": "Strip", "content": " ", "start": 1, "stop": 0},
        ],
    }
    return _match(_target_description, decoder)


def _is_spm_decoder_no_space(decoder):
    _target_description = {
        "type": "Sequence",
        "decoders": [
            {"type": "Replace", "pattern": {"String": "▁"}, "content": " "},
            {"type": "ByteFallback"},
            {"type": "Fuse"},
        ],
    }
    return _match(_target_description, decoder)


def _is_bpe_decoder(decoder):
    return isinstance(decoder, dict) and decoder.get("type", None) == "ByteLevel"


def load_tokenizer(model_path, return_tokenizer=True, tokenizer_config_extra={}):
    """Load a huggingface tokenizer and try to infer the type of streaming
    detokenizer to use.

    Note, to use a fast streaming tokenizer, pass a local file path rather than
    a Hugging Face repo ID.
    """
    detokenizer_class = NaiveStreamingDetokenizer

    tokenizer_file = model_path / "tokenizer.json"
    if tokenizer_file.exists():
        with open(tokenizer_file, "r") as f:
            try:
                tokenizer_content = json.load(f)
            except JSONDecodeError as e:
                raise JSONDecodeError("Failed to parse tokenizer.json", e.doc, e.pos)

        if "decoder" in tokenizer_content:
            if _is_spm_decoder(tokenizer_content["decoder"]):
                detokenizer_class = SPMStreamingDetokenizer
            elif _is_spm_decoder_no_space(tokenizer_content["decoder"]):
                detokenizer_class = partial(SPMStreamingDetokenizer, trim_space=False)
            elif _is_bpe_decoder(tokenizer_content["decoder"]):
                detokenizer_class = BPEStreamingDetokenizer

    if return_tokenizer:
        return TokenizerWrapper(
            AutoTokenizer.from_pretrained(model_path, **tokenizer_config_extra),
            detokenizer_class,
        )
    else:
        return detokenizer_class
